import{_ as t,o,c as n,a2 as i}from"./chunks/framework.BEUshCVJ.js";const d=JSON.parse('{"title":"High latency","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/latency.md","filePath":"troubleshooting/latency.md","lastUpdated":1793315481000}'),s={name:"troubleshooting/latency.md"};function a(r,e,l,h,c,g){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="high-latency" tabindex="-1">High latency <a class="header-anchor" href="#high-latency" aria-label="Permalink to &quot;High latency&quot;">​</a></h1><p>This page helps when hints take noticeably longer than about one and a half seconds, or when requests fail on some networks.</p><h2 id="slow-hints" tabindex="-1">Hints take more than two or three seconds <a class="header-anchor" href="#slow-hints" aria-label="Permalink to &quot;Hints take more than two or three seconds {#slow-hints}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>The endpoint chosen earlier is no longer the fastest from your current network.</li><li>The hint model or the detection model is a large, slower model.</li><li><strong>Write hints while checking the question</strong> is off, so hints wait for detection to finish.</li><li>Long briefing material makes every request larger.</li><li>The sentence-end silence is long.</li><li>A VPN or proxy adds a long detour.</li></ol><p><strong>Check</strong></p><ol><li>Hover over the latency figure in the panel footer: it shows how the last hint&#39;s time split between recognition, detection and hints, and the median.</li><li>When hints are slow several times in a row, the panel names the slowest stage and the one change that helps most, with a button to that setting.</li><li>Open <strong>Settings › Diagnostics</strong>: each hint shows how long recognition, detection and hint generation took.</li></ol><p><strong>Fix</strong></p><ol><li>Keep <strong>Write hints while checking the question</strong> and <strong>Early trigger</strong> on in <strong>Settings › Hints</strong>. Together they save about a second on most questions.</li><li>Run the <a href="/meetcue/guide/latency">latency probe</a> again and apply the fastest combination.</li><li>Choose a faster hint model, and a small, fast detection model: detection only answers yes or no. The probe&#39;s combination table shows the difference.</li><li>Shorten the briefing material to what this meeting needs.</li><li>Lower <strong>Sentence end after silence</strong> in <strong>Settings › Audio › Advanced</strong> a little.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="probe-again" tabindex="-1">The panel suggests running the probe again <a class="header-anchor" href="#probe-again" aria-label="Permalink to &quot;The panel suggests running the probe again {#probe-again}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>Three questions in a row took longer than 2.5 seconds.</li></ol><p><strong>Check</strong></p><ol><li>Compare the current latency with your last probe results.</li></ol><p><strong>Fix</strong></p><ol><li>Click <strong>Open latency probe</strong> in the notice and run it. Give it a network label so you can compare places later.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="company-network" tabindex="-1">Connections fail on a company network <a class="header-anchor" href="#company-network" aria-label="Permalink to &quot;Connections fail on a company network {#company-network}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>The network inspects HTTPS traffic with its own certificate (<a href="/meetcue/troubleshooting/error-codes#mc-net-001">MC-NET-001</a>).</li><li>Internet access goes through a proxy that MeetCue doesn&#39;t know about.</li><li>The firewall blocks WebSocket connections, which speech recognition uses.</li></ol><p><strong>Check</strong></p><ol><li>Open the provider&#39;s website in a browser on the same computer.</li><li>Ask your IT department whether a proxy is required and whether its certificate is installed in Windows.</li></ol><p><strong>Fix</strong></p><ol><li>MeetCue trusts certificates installed in Windows. Ask IT to install the company certificate in the Windows certificate store if it isn&#39;t.</li><li>Enter the proxy in <strong>Settings › Providers &amp; cost › Advanced › HTTPS proxy</strong>, for example <code>http://proxy.example.com:8080</code>.</li><li>Ask IT to allow WebSocket connections to your speech recognition provider&#39;s host names shown in the latency probe.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p>',26)])])}const u=t(s,[["render",a]]);export{d as __pageData,u as default};
